-- Boundary Oak Distillery importer (bourbon.boundary_oak) — applied 2026-10-12 via Supabase MCP execute_sql.
-- The Lincoln page states PROOF 105-120 / AGE 2-4 YEARS for the line (a range), so no Lincoln row is corrected or confirmed;
-- the manual 'Lincoln 8 Year Single Barrel' and the two seeds are untouched. Adds the six bottlings whose pages state one proof.
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"War Eagle","rar":"shelf","f":"War Eagle","x":null,"p":101.0,"ay":null,"al":"2–4 yr","nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":[],"img":"https://images.squarespace-cdn.com/content/v1/670931b168bf612c4bf24df3/86e835eb-e905-4f32-bfc4-5db11556b366/WAR-EAGLE-PNG.png","u":"https://www.boundaryoak.co/war-eagle","pr":"Boundary Oak Distillery","mk":"e76e539c-7222-4d77-a625-f60ae27f1788"},{"n":"St. Michael","rar":"shelf","f":"St. Michael","x":null,"p":105.0,"ay":null,"al":"2–4 yr","nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":[],"img":"https://images.squarespace-cdn.com/content/v1/670931b168bf612c4bf24df3/80af4751-ad84-41ee-ac7c-313b93dad643/RED-ST-MICHAEL-PNG.png","u":"https://www.boundaryoak.co/st-michael","pr":"Boundary Oak Distillery","mk":"e76e539c-7222-4d77-a625-f60ae27f1788"},{"n":"St. Michael Special Edition","rar":"limited","f":"St. Michael","x":"Special Edition","p":105.0,"ay":null,"al":"2–4 yr","nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":[],"img":"https://images.squarespace-cdn.com/content/v1/670931b168bf612c4bf24df3/fcd4c5e3-aad5-465e-998a-b1cb147255fd/BLUE-ST-MICHAEL-PNG.png","u":"https://www.boundaryoak.co/st-michael-special-edition","pr":"Boundary Oak Distillery","mk":"e76e539c-7222-4d77-a625-f60ae27f1788"},{"n":"Big Red 1","rar":"shelf","f":"Big Red 1","x":null,"p":100.0,"ay":null,"al":"2–4 yr","nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":[],"img":"https://images.squarespace-cdn.com/content/v1/670931b168bf612c4bf24df3/49d25a01-b581-4525-ac01-39da96998f7c/BIG-RED-1-PNG.png","u":"https://www.boundaryoak.co/big-red-1","pr":"Boundary Oak Distillery","mk":"e76e539c-7222-4d77-a625-f60ae27f1788"},{"n":"Patton","rar":"shelf","f":"Patton","x":null,"p":105.0,"ay":null,"al":"5+ yr","nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":["G. S. Patton Jr. Bourbon","Patton Bourbon","Patton Bourbon Whiskey"],"img":"https://images.squarespace-cdn.com/content/v1/670931b168bf612c4bf24df3/1df7e418-0c95-4dc2-bf98-53ce91c21a90/patton-bourbon-PNG.png","u":"https://www.boundaryoak.co/patton-bourbon","pr":"Boundary Oak Distillery","mk":"e76e539c-7222-4d77-a625-f60ae27f1788"},{"n":"Iron Mike","rar":"shelf","f":"Iron Mike","x":null,"p":96.0,"ay":5.0,"al":"5 yr","nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":["Iron Mike Bourbon"],"img":"https://images.squarespace-cdn.com/content/v1/670931b168bf612c4bf24df3/643ffb86-cdd0-4d6d-b54b-39fb62e1f214/IRON-MIKE-png-.png","u":"https://www.boundaryoak.co/iron-mike","pr":"Boundary Oak Distillery","mk":"e76e539c-7222-4d77-a625-f60ae27f1788"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
